CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0,profile TEXT NOT NULL DEFAULT '{}');
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires BIGINT NOT NULL);
CREATE TABLE account_links(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,expires BIGINT NOT NULL);
CREATE TABLE limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset BIGINT NOT NULL);
CREATE TABLE prices(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product TEXT NOT NULL,store TEXT NOT NULL,scope TEXT NOT NULL,branch TEXT NOT NULL,name TEXT NOT NULL,brand TEXT NOT NULL,category TEXT NOT NULL,price DOUBLE PRECISION NOT NULL CHECK(price>0),currency TEXT NOT NULL,available INTEGER,url TEXT NOT NULL,checked TEXT NOT NULL,promotion TEXT NOT NULL,source TEXT NOT NULL,fingerprint TEXT NOT NULL UNIQUE);
CREATE INDEX price_series ON prices(product,store,scope,branch,currency,promotion,checked);
CREATE INDEX prices_time ON prices(checked);
CREATE TABLE source_runs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,source TEXT NOT NULL,started TEXT NOT NULL,status TEXT NOT NULL,count INTEGER NOT NULL,error TEXT NOT NULL);
CREATE INDEX source_run_time ON source_runs(source,started);
CREATE TABLE follows(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,preferences TEXT NOT NULL);
CREATE TABLE changes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,signature TEXT NOT NULL UNIQUE,event TEXT NOT NULL,detected BIGINT NOT NULL);
CREATE TABLE inbox(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,change_id BIGINT NOT NULL REFERENCES changes(id),seen BIGINT,pushed BIGINT,PRIMARY KEY(user_id,change_id));
CREATE INDEX inbox_pending ON inbox(user_id,pushed,change_id);
CREATE TABLE subscriptions(endpoint TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,subscription TEXT NOT NULL);
CREATE TABLE saved_reports(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,payload TEXT NOT NULL,created TEXT NOT NULL);
CREATE INDEX report_owner ON saved_reports(user_id,created);
CREATE TABLE projects(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, payload TEXT NOT NULL);
ALTER TABLE users ADD COLUMN local_only INTEGER NOT NULL DEFAULT 0;
CREATE TABLE trade_companies (id TEXT PRIMARY KEY, name TEXT NOT NULL, created TEXT NOT NULL);
ALTER TABLE users ADD COLUMN trade_only INTEGER NOT NULL DEFAULT 0;
CREATE TABLE trade_identities ("user" TEXT PRIMARY KEY REFERENCES users(id), email TEXT NOT NULL UNIQUE);
CREATE TABLE trade_members (company TEXT NOT NULL REFERENCES trade_companies(id), "user" TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','supervisor','relevador')), active INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(company,"user"));
CREATE INDEX trade_member_user ON trade_members("user",active);
CREATE TABLE trade_invites (token TEXT PRIMARY KEY, company TEXT NOT NULL REFERENCES trade_companies(id), email TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL, expires BIGINT NOT NULL);
CREATE UNIQUE INDEX trade_pending_invites ON trade_invites(company,email);
CREATE TABLE trade_visits (company TEXT NOT NULL REFERENCES trade_companies(id), id TEXT NOT NULL, "user" TEXT NOT NULL REFERENCES users(id), store TEXT NOT NULL, branch TEXT NOT NULL, address TEXT NOT NULL, zone TEXT NOT NULL, checked TEXT NOT NULL, lat DOUBLE PRECISION, lng DOUBLE PRECISION, PRIMARY KEY(company,id));
CREATE INDEX trade_visit_owner ON trade_visits(company,"user",checked);
CREATE TABLE trade_prices (id TEXT PRIMARY KEY, company TEXT NOT NULL REFERENCES trade_companies(id), visit TEXT NOT NULL, "user" TEXT NOT NULL REFERENCES users(id), product TEXT NOT NULL, place TEXT NOT NULL, checked TEXT NOT NULL, payload TEXT NOT NULL, photo BYTEA, mime TEXT, status TEXT NOT NULL CHECK(status IN ('pendiente','validado','rechazado')), version INTEGER NOT NULL, FOREIGN KEY(company,visit) REFERENCES trade_visits(company,id));
CREATE INDEX trade_price_series ON trade_prices(company,product,place,status,checked);
CREATE UNIQUE INDEX trade_confirmed_at ON trade_prices(company,product,place,checked) WHERE status='validado';
CREATE TABLE trade_audit (seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company TEXT NOT NULL REFERENCES trade_companies(id), price TEXT NOT NULL REFERENCES trade_prices(id), actor TEXT NOT NULL REFERENCES users(id), at TEXT NOT NULL, action TEXT NOT NULL, note TEXT NOT NULL, snapshot TEXT NOT NULL);
CREATE INDEX trade_audit_price ON trade_audit(company,price,seq);
CREATE TABLE trade_own (company TEXT NOT NULL REFERENCES trade_companies(id), product TEXT NOT NULL, scope TEXT NOT NULL, checked TEXT NOT NULL, price INTEGER NOT NULL, PRIMARY KEY(company,product,scope,checked));
CREATE TABLE trade_rules (id TEXT PRIMARY KEY, company TEXT NOT NULL REFERENCES trade_companies(id), payload TEXT NOT NULL);
CREATE TABLE trade_alerts (id TEXT PRIMARY KEY, company TEXT NOT NULL REFERENCES trade_companies(id), price TEXT NOT NULL REFERENCES trade_prices(id), version INTEGER NOT NULL, previous TEXT NOT NULL REFERENCES trade_prices(id), previous_version INTEGER NOT NULL, created TEXT NOT NULL, payload TEXT NOT NULL, UNIQUE(price,version,previous,previous_version));
CREATE INDEX trade_alert_company ON trade_alerts(company,created);
CREATE TABLE trade_push (company TEXT NOT NULL, "user" TEXT NOT NULL, endpoint TEXT NOT NULL, subscription TEXT NOT NULL, PRIMARY KEY(company,"user",endpoint), FOREIGN KEY(company,"user") REFERENCES trade_members(company,"user"));
CREATE TABLE trade_push_delivery (alert TEXT NOT NULL REFERENCES trade_alerts(id), "user" TEXT NOT NULL, endpoint TEXT NOT NULL, sent TEXT NOT NULL, PRIMARY KEY(alert,"user",endpoint));
CREATE TABLE trade_signups (token TEXT PRIMARY KEY, email TEXT NOT NULL, company TEXT NOT NULL, name TEXT NOT NULL, expires BIGINT NOT NULL); CREATE INDEX trade_signup_email ON trade_signups(email);
CREATE TABLE platform_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX account_links_user_kind ON account_links(user_id,kind);
CREATE INDEX sessions_expiration ON sessions(expires);
